'use strict';
let rhythmMotionPaused = false;
const $ = (s,root=document) => root.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>\x22']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\x22':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-6v-7h-4v7H4a1 1 0 0 1-1-1Z',compass:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM16 8l-2 6-6 2 2-6Z',target:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0ZM12 12h.01',route:'M5 4a2 2 0 1 0 0 .01M19 20a2 2 0 1 0 0 .01M7 4h9a4 4 0 0 1 0 8H8a4 4 0 0 0 0 8h9',chart:'M4 3v17h17M8 15l4-4 4 2 5-7',book:'M4 4h7a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4ZM20 4h-3a3 3 0 0 0-3 3v14a4 4 0 0 1 4-2h2Z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM22 21v-2a4 4 0 0 0-3-3.87M16 3a4 4 0 0 1 0 8',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z',help:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM9 9a3 3 0 0 1 6 0c0 2-3 2-3 5M12 17h.01',arrow:'M5 12h14M14 7l5 5-5 5',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',check:'m5 12 4 4L19 6',plus:'M12 5v14M5 12h14',close:'m6 6 12 12M6 18 18 6',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 7v5l3 2',sun:'M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M5 19l1-1M18 6l1-1',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5ZM20 3v4M18 5h4',leaf:'M20 3C7 2 2 8 5 15s16 4 15-12ZM5 19l11-11',flame:'M12 3c1 5-5 6-3 10 1-2 3-2 4-4 4 4 6 7 3 11-7 6-15-2-9-9-1 4 2 4 2 2',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9ZM10 21h4',menu:'M4 6h16M4 12h16M4 18h16',up:'m6 15 5-5 4 3 5-7M15 6h5v5',brief:'M8 7V4h8v3M3 7h18v14H3ZM3 12c5 3 13 3 18 0M10 13h4',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0l-1 1-1-1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',edit:'m16 3 5 5-12 12-6 1 1-6ZM13 6l5 5',calendar:'M4 5h16v16H4ZM7 3v4M17 3v4M4 10h16',shield:'m12 3 8 3v6c0 5-8 9-8 9S4 17 4 12V6ZM8 12l3 3 5-6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',moon:'M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11',cloud:'M6 18a4 4 0 0 1-1-8 6 6 0 0 1 11-2 5 5 0 1 1 1 10Z',battery:'M3 7h15v10H3ZM21 10v4M6 10v4M10 10v4M14 10v4',smile:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM8 9h.01M16 9h.01M8 14c2 3 6 3 8 0',flag:'M4 22V3c6-4 10 4 16 0v12c-6 4-10-4-16 0',logout:'M9 4H4v16h5M12 12h9m-4-4 4 4-4 4'};
const icon=(name,cls='')=>`<svg class='icon ${cls}' viewBox='0 0 24 24' aria-hidden='true'><path d='${paths[name]||paths.spark}'/></svg>`;
const brand=()=>`<span class='brand'><img class='brand-mark' src='favicon.svg' alt=''><span>greatnessly<span class='brand-dot'>.</span></span></span>`;
const button=(text,action,variant='primary',ico='arrow')=>`<button class='btn btn-${variant}' data-action='${action}'>${text}${ico?icon(ico):''}</button>`;
const todayKey=()=>new Date().toLocaleDateString('en-CA');
const seed=()=>({version:2,mode:'sample',name:'Maya Bennett',vision:'I am a purposeful leader who creates meaningful work, protects my energy, and shows up for the people who matter.',values:['Purpose','Growth','Well-being'],identity:'Intentional. Consistent. Courageous.',growth:'Protecting my focus and following through on the promises I make to myself.',day:18,start:todayKey(),goals:[{id:'g1',title:'Launch my consulting practice',category:'Career',progress:35,why:'Create meaningful work on my own terms.',milestones:['Define my offer','Speak to 5 potential clients','Sign my first client']},{id:'g2',title:'Build a stronger, healthier me',category:'Health',progress:52,why:'Have energy for the life I want to build.',milestones:['Move 4 days this week','Build a consistent sleep routine','Complete a 5K walk']},{id:'g3',title:'Be more present with my people',category:'Relationships',progress:28,why:'Invest in the relationships that make life meaningful.',milestones:['Plan a weekly intentional catch-up','Set phone-free evenings','Celebrate a shared milestone']}],tasks:[{id:'t1',title:'Move my body for 20 minutes',goal:'Build a stronger, healthier me',category:'Health',mins:20,done:true},{id:'t2',title:'Outline my first service offering',goal:'Launch my consulting practice',category:'Career',mins:30,done:false},{id:'t3',title:'Have one meaningful conversation',goal:'Be more present with my people',category:'Relationships',mins:15,done:false}],checkin:null,entries:[],posts:[],rsvp:false,cheers:[],notifications:{daily:true,weekly:true},lastActive:todayKey()});
let state;let storageOkay=true;try{state=JSON.parse(localStorage.getItem('greatnessly-v2'))||seed();if(state.version!==2)state=seed();}catch{state=seed();storageOkay=false;}
if(state.lastActive!==todayKey()){state.tasks.forEach(t=>t.done=false);state.checkin=null;state.lastActive=todayKey();}
let currentPage='today',goalFilter='All goals',modalType=null,modalStep=0,draft={},lastFocus=null,toastTimer;
function save(){try{localStorage.setItem('greatnessly-v2',JSON.stringify(state));return true;}catch{storageOkay=false;toast('Browser storage is unavailable. Changes last until this page closes.');return false;}}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4000);}
const completed=()=>state.tasks.filter(t=>t.done).length;
function scoreData(){const sample=state.mode==='sample';const done=(sample?15:0)+completed();const planned=(sample?18:0)+state.tasks.length;const checks=(sample?6:0)+(state.checkin?1:0);const days=sample?7:1;const rating=state.checkin?Number(state.checkin.alignment):sample?3:0;const score=Math.round((planned?done/planned:0)*50+(checks/days)*30+(rating/5)*20);return{done,planned,checks,days,rating,score:Math.min(100,score),forming:!sample&&!state.checkin};}
function titleBlock(eyebrow,title,desc,action=''){return `<div class='page-header'><div><div class='eyebrow'>${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;}
function avatars(){return `<div class='avatars'><span class='avatar'>JL</span><span class='avatar'>AS</span><span class='avatar'>DK</span><span class='avatar'>+3</span></div>`;}
function tag(category){return `<span class='tag ${category==='Health'?'teal':category==='Relationships'?'gold':''}'>${esc(category)}</span>`;}
const nav=[['today','home','My day'],['future','compass','My future self'],['goals','target','Goals & actions'],['journey','route','My 90-day journey'],['insights','chart','Progress & insights'],['journal','book','Reflection journal']];
const pageNames={today:'My day',future:'My future self',goals:'Goals & actions',journey:'My 90-day journey',insights:'Progress & insights',journal:'Reflection journal',circle:'My circle',settings:'Settings',help:'Help & support',founder:'The product story'};
function navigate(page){if(page==='welcome'){currentPage=page;location.hash='welcome';render();return;}currentPage=Object.hasOwn(pageNames,page)?page:'today';location.hash=currentPage;render();window.scrollTo({top:0,behavior:'instant'});}
function render(){document.title=`${pageNames[currentPage]||'Become who you imagine'} · Greatnessly`;if(currentPage==='welcome'){renderLanding();enhanceExperience();return;}const name=state.name.split(' ')[0];const day=state.day;$('#app').innerHTML=`<div class='app-shell'><div class='mobile-shade' data-action='close-menu'></div><aside class='sidebar' aria-label='Main navigation'><a href='#today' data-page='today' aria-label='Greatnessly home'>${brand()}</a><div class='workspace-label'>YOUR SPACE FOR BECOMING</div><nav class='nav-group'>${nav.map(([id,ico,label])=>`<button class='nav-item ${currentPage===id?'active':''}' data-page='${id}' ${currentPage===id?"aria-current='page'":''}>${icon(ico)}${label}</button>`).join('')}</nav><div class='nav-section-label'>GROW TOGETHER</div><nav class='nav-group'><button class='nav-item ${currentPage==='circle'?'active':''}' data-page='circle'>${icon('users')}My circle</button></nav><div class='sidebar-bottom'><button class='journey-mini' style='text-align:left;width:calc(100% - 18px)' data-page='journey'><div class='mini-row'>Your 90-day journey <span>${Math.round(day/90*100)}%</span></div><div class='bar'><span style='width:${day/90*100}%'></span></div><p>Day ${day} of 90 · Keep becoming.</p></button><button class='nav-item' data-page='help'>${icon('help')}Help & support</button><button class='profile-button' data-page='settings'><span class='avatar'>${esc(state.name.split(' ').map(x=>x[0]).join('').slice(0,2))}</span><span><strong>${esc(state.name)}</strong><small>${state.mode==='sample'?'Founding member · sample':'Your new journey'}</small></span>${icon('settings')}</button></div></aside><div class='main-wrap'><header class='topbar'><button class='icon-btn mobile-menu' data-action='menu' aria-label='Open navigation'>${icon('menu')}</button><div class='breadcrumb'><span>Your journey</span><span>/</span><b>${pageNames[currentPage]}</b></div><div class='top-actions'><button class='demo-tag' data-action='demo-info'>INTERACTIVE PREVIEW</button><span class='top-date'>${new Date().toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'})}</span><button class='icon-btn' data-action='notifications' aria-label='Notifications'>${icon('bell')}<span class='notification-dot'></span></button></div></header><main id='main' tabindex='-1'><div>${({today:renderToday,future:renderFuture,goals:renderGoals,journey:renderJourney,insights:renderInsights,journal:renderJournal,circle:renderCircle,settings:renderSettings,help:renderHelp,founder:renderFounder}[currentPage])()}</div><footer class='page-footer'><span class='footer-motto'>A little more aligned. A little more you.</span><div><button data-page='founder'>The product story</button><span> &nbsp;·&nbsp; </span><button data-action='demo-info'>About this preview</button></div></footer></main></div></div>`;enhanceExperience();}
function renderToday(){const s=scoreData();const count=completed();return `${titleBlock('A NEW DAY. A LITTLE CLOSER.',`Keep becoming, ${esc(state.name.split(' ')[0])}.`,'Your future is built in the small things you do today.',`<button class='journey-pill' data-page='journey'>${icon('leaf')}<strong>Day ${state.day}</strong><span>of your 90-day journey</span></button>`)}<div class='dashboard-top'><section class='hero'><div class='eyebrow'>YOUR NEXT CHAPTER IS ALREADY HAPPENING</div><h2>Your future self<br>starts with <em>today.</em></h2><p>Pause. Set an intention. Take one small step toward the person you want to become.</p><div class='hero-bottom'>${button(state.checkin?'View today’s reflection':'Start my daily check-in','checkin','light') }<span>${icon('clock').replace("class='icon'","class='icon' style='width:10px;height:10px;vertical-align:middle'")} ${state.checkin?'A promise to yourself, kept':'2 minutes. Just for you.'}</span></div></section><section class='score-card'><div class='card-heading'><h2>Your Greatnessly Score</h2><button class='icon-btn' style='width:20px;height:20px' data-action='score-info' aria-label='How your score works'>${icon('help')}</button></div><div class='score-ring'><svg viewBox='0 0 144 144' aria-hidden='true'><circle cx='72' cy='72' r='58' fill='none' stroke='#f0f3f4' stroke-width='8'/><circle cx='72' cy='72' r='58' fill='none' stroke='#74a899' stroke-width='8' stroke-linecap='round' stroke-dasharray='${s.forming?0:s.score/100*364.4} 364.4'/><circle cx='72' cy='72' r='46' fill='none' stroke='#f2f4f6' stroke-width='1' stroke-dasharray='1 6'/></svg><div class='score-inner'><strong>${s.forming?'—':s.score}</strong><span>${s.forming?'BASELINE FORMING':'OUT OF 100'}</span></div></div><div class='score-caption'>${icon('up')}${s.forming?'Your first check-in starts the story':state.mode==='sample'?'Steady steps. Real momentum.':'Your starting point, made visible.'}</div><div class='score-footer'>${state.mode==='sample'?'Illustrative 7-day data':'Based on your activity'} · <button data-action='score-info'>See the breakdown</button></div></section></div><div class='stats-row'><div class='stat'><span class='stat-icon'>${icon('check')}</span><div class='stat-data'><strong>${count}<small>of ${state.tasks.length}</small></strong><p>Promises kept today</p></div><span class='stat-note'>${count===state.tasks.length?'Beautiful work':'One step at a time'}</span></div><div class='stat'><span class='stat-icon'>${icon('flame')}</span><div class='stat-data'><strong>${state.mode==='sample'?(state.checkin?7:6):(state.checkin?1:0)}<small>${state.mode==='sample'?'of 7 days':'day'}</small></strong><p>Showing up this week</p></div></div><div class='stat'><span class='stat-icon'>${icon('target')}</span><div class='stat-data'><strong>${state.goals.length}<small>${state.goals.length===1?'goal':'goals'}</small></strong><p>Moving you forward</p></div><button class='text-button' data-page='goals' aria-label='View goals'>${icon('arrow')}</button></div></div><div class='dashboard-middle'><section><div class='section-heading'><h2>Today’s small promises <small>${count}/${state.tasks.length} complete</small></h2><button class='text-button' data-page='goals'>View my goals ${icon('arrow')}</button></div><div class='action-list'>${renderTasks()}</div></section><section><div class='section-heading'><h2>A moment of perspective</h2><span class='tag slate'>${state.mode==='sample'?'SAMPLE INSIGHT':'REFLECTION GUIDE'}</span></div><div class='insight-card'><div class='insight-label'>${icon('spark')} YOUR INNER COMPASS</div><h3>${state.mode==='sample'?'You don’t need more time.<br>You need a little more intention.':'Your next step can be smaller than you think.'}</h3><p>${state.mode==='sample'?'In this sample week, morning actions were completed more often. What could you make room for before the day gets busy?':'Choose a promise so small it still fits a difficult day. Consistency starts with something you can return to.'}</p><button class='text-button' data-action='reflection-guide'>Explore this reflection ${icon('arrow')}</button></div></section></div><div class='dashboard-bottom'><section><div class='section-heading'><h2>The little things add up</h2><button class='text-button' data-page='insights'>See my progress ${icon('arrow')}</button></div><div class='card week-card'><div class='card-heading'><span class='small' style='font-size:11px;font-weight:600'>Your week at a glance</span><span class='muted' style='font-size:9px'>${state.mode==='sample'?'Illustrative activity':'This journey’s first week'}</span></div><div class='week-days'>${['M','T','W','T','F','S','S'].map((d,i)=>`<div class='week-day'><span>${d}</span><div class='day-circle ${state.mode==='sample'&&i<5?'complete':i===5?'current':''}'>${state.mode==='sample'&&i<5?icon('check'):i===5?(state.checkin?icon('check'):String(state.day)):'·'}</div></div>`).join('')}</div><p class='week-caption'>${icon('spark')}${state.mode==='sample'?'Every day is a new chance to show up for yourself.':'Your check-ins will build a picture of your progress.'}</p></div></section><section><div class='section-heading'><h2>Better, together</h2><button class='text-button' data-page='circle'>My circle ${icon('arrow')}</button></div><div class='card week-card'><div class='circle-event'><div class='calendar-icon'><span>WEEK</span><strong>03</strong></div><div><h3>The weekly reset</h3><p>Sunday · 6:00 PM CT · 45 min</p><span class='tag slate' style='font-size:7px;margin-top:5px'>SAMPLE SESSION</span></div></div><div class='circle-footer'>${avatars()}<span>Your growth circle</span><button class='text-button' data-action='rsvp'>${state.rsvp?'Reserved ✓':'View session'} ${icon('arrow')}</button></div></div></section></div>`;}
function renderTasks(){if(!state.tasks.length)return `<div class='empty'>${icon('leaf')}<h3>A small promise is a good start.</h3><p>Add your first action to bring your goal into today.</p>${button('Add an action','add-action','outline','plus')}</div>`;return state.tasks.map(t=>`<div class='action-row ${t.done?'done':''}'><button class='check-button ${t.done?'checked':''}' data-action='toggle-task' data-id='${esc(t.id)}' aria-label='${t.done?'Mark incomplete':'Complete'}: ${esc(t.title)}' aria-pressed='${t.done}'>${t.done?icon('check'):''}</button><div class='action-main'><strong>${esc(t.title)}</strong><p>${esc(t.goal)}</p></div>${tag(t.category)}<span class='action-duration'>${icon('clock')}${t.mins} min</span></div>`).join('');}
function renderFuture(){return `${titleBlock('YOUR NORTH STAR','Meet the person you’re becoming.','A clear direction makes the next small step easier.',button('Edit my blueprint','edit-profile','outline','edit'))}<div class='grid-2'><section class='card profile-vision'><div class='eyebrow' style='color:#759489'>MY FUTURE SELF</div><blockquote>“${esc(state.vision)}”</blockquote><div class='eyebrow' style='color:#8ca397'>THE PERSON I AM PRACTICING BEING</div><div style='margin-top:12px'>${state.identity.split(/[.,]/).filter(x=>x.trim()).map(x=>`<span class='identity-chip'>${icon('leaf')}${esc(x.trim())}</span>`).join('')}</div><p class='profile-footnote'>Your identity is a direction, not a destination. You can refine it as you grow.</p></section><div class='stack'><section class='card'><div class='section-heading'><h2>What matters to me</h2>${icon('compass')}</div><p class='helper'>The values I want my choices to reflect.</p><div class='value-list'>${state.values.map(v=>`<span class='value-chip'>${esc(v)}</span>`).join('')}</div></section><section class='card'><div class='section-heading'><h2>Where I’m growing</h2>${icon('leaf')}</div><p class='helper'>${esc(state.growth)}</p></section></div></div><div class='section-heading wide-spaced'><h2>My vision, in motion</h2><button class='text-button' data-page='goals'>Explore my goals ${icon('arrow')}</button></div><div class='grid-3'>${state.goals.slice(0,3).map(g=>goalCard(g)).join('')}</div><div class='scope-label'>Try the first-time experience: build a future-self blueprint and one daily promise in three short steps. ${button('Start a fresh journey','new-journey','outline','arrow')}</div>`;}
function goalCard(g){return `<article class='card goal-card'><div style='display:flex;justify-content:space-between;align-items:flex-start'><span class='goal-icon'>${icon(g.category==='Health'?'heart':g.category==='Relationships'?'users':'brief')}</span>${tag(g.category)}</div><h3>${esc(g.title)}</h3><p>${esc(g.why||'A meaningful step toward my future self.')}</p><div class='bar'><span style='width:${g.progress}%'></span></div><div class='goal-card-footer'><span>${g.progress}% of milestones</span><button class='text-button' data-action='goal-detail' data-id='${esc(g.id)}'>View plan ${icon('arrow')}</button></div></article>`;}
function renderGoals(){const goals=state.goals.filter(g=>goalFilter==='All goals'||g.category===goalFilter);return `${titleBlock('TURN INTENTION INTO ACTION','Big dreams. Small, doable steps.','Create a meaningful outcome, then give it a place in your day.',button('Add a goal','add-goal','primary','plus'))}<div class='filters' aria-label='Filter goals'>${['All goals','Career','Health','Relationships','Financial','Personal'].map(f=>`<button class='filter ${f===goalFilter?'active':''}' data-action='filter' data-filter='${f}' aria-pressed='${f===goalFilter}'>${f}</button>`).join('')}</div><div class='grid-3'>${goals.map(g=>goalCard(g)).join('')}${!goals.length?`<div class='card empty'>${icon('target')}<h3>Make room for what matters.</h3><p>No ${goalFilter==='All goals'?'':goalFilter.toLowerCase()} goals yet. Start with one meaningful outcome.</p></div>`:''}<button class='card goal-card goal-add' data-action='add-goal'>${icon('plus')}<strong>A new possibility</strong><span class='small'>What would make these 90 days meaningful?</span></button></div><div class='section-heading wide-spaced'><h2>Today’s action plan</h2><button class='btn btn-outline' data-action='add-action'>${icon('plus')}Add an action</button></div><div class='action-list'>${renderTasks()}</div><p class='helper' style='margin-top:13px'>Your daily promises contribute to your behavior score. Goal milestones are tracked separately.</p>`;}
function renderJourney(){return `${titleBlock('THE 90-DAY GREATNESS JOURNEY','A chapter worth showing up for.','You don’t need to have it all figured out. You just need your next step.')}<div class='journey-banner'><div><div class='eyebrow' style='color:#a4c2bd'>YOUR JOURNEY · ${state.mode==='sample'?'ILLUSTRATIVE PROGRESS':'A NEW BEGINNING'}</div><h2>Build the roots.<br>The growth will follow.</h2><p>You’re in the Foundation phase. Build clarity, find your rhythm, and practice keeping one small promise at a time.</p></div><div class='journey-number'>${state.day}<small>OF 90 DAYS</small></div></div><div class='phase current'><div class='eyebrow'>DAYS 01—30</div><h3>01 &nbsp; Foundation</h3><p>Get clear on who you’re becoming. Choose one meaningful goal and create a daily rhythm that fits your real life.</p><span class='tag teal'>YOU ARE HERE</span></div><div class='card'><div class='section-heading'><h2>One day at a time</h2><span class='small muted'>${state.mode==='sample'?'Sample journey map':'Your journey map'}</span></div><div class='journey-grid'>${Array.from({length:90},(_,i)=>{const n=i+1;return `<button class='journey-day ${n<state.day?(n===7||n===13?'missed':'past'):n===state.day?'today':''}' data-action='journey-day' data-day='${n}' aria-label='Day ${n}${n===state.day?', today':''}'>${String(n).padStart(2,'0')}</button>`;}).join('')}</div><p class='helper' style='margin-top:22px'><span style='color:#6f9c84'>●</span> Showed up &nbsp; <span style='color:#c2ac73'>●</span> A pause &nbsp; <span style='color:var(--navy)'>●</span> Today &nbsp; · &nbsp; A pause is part of the journey. Your progress stays with you.</p></div><div class='phase'><div class='eyebrow'>DAYS 31—60</div><h3>02 &nbsp; Momentum</h3><p>Notice what works. Adjust what doesn’t. Deepen your habits and turn your growing clarity into meaningful progress.</p><span class='tag slate'>UP NEXT</span></div><div class='phase'><div class='eyebrow'>DAYS 61—90</div><h3>03 &nbsp; Becoming</h3><p>Reflect on the evidence of your growth. Celebrate what’s changed and choose what you’ll carry into your next chapter.</p><span class='tag slate'>ON THE HORIZON</span></div>`;}
function renderInsights(){const s=scoreData();return `${titleBlock('THE EVIDENCE OF BECOMING','Look how far you’re coming.','Patterns to learn from. Progress to feel good about.',button('How scoring works','score-info','outline','help'))}<div class='grid-2'><section class='card chart-card'><div class='section-heading'><h2>Your alignment, over time</h2><span class='tag slate'>${state.mode==='sample'?'SAMPLE · 18 DAYS':'YOUR BASELINE'}</span></div>${state.mode==='sample'?`<div class='chart'><svg viewBox='0 0 600 200' role='img' aria-label='Illustrative growth score trend from 42 on day one to 76 on day eighteen'><defs><linearGradient id='chart-fill' x1='0' x2='0' y1='0' y2='1'><stop offset='0' stop-color='#b5d8c7' stop-opacity='.5'/><stop offset='1' stop-color='#e6f2ec' stop-opacity='.05'/></linearGradient></defs><g stroke='#ecf0f4' stroke-dasharray='3 5'><path d='M0 20h600M0 70h600M0 120h600M0 170h600'/></g><path d='M0 170 36 155 72 159 108 133 144 142 180 116 216 124 252 85 288 95 324 75 360 87 396 57 432 64 468 39 504 48 540 26 576 32 600 18V200H0Z' fill='url(#chart-fill)'/><path d='M0 170 36 155 72 159 108 133 144 142 180 116 216 124 252 85 288 95 324 75 360 87 396 57 432 64 468 39 504 48 540 26 576 32 600 18' stroke='#71a78f' stroke-width='3' stroke-linejoin='round' fill='none'/><circle cx='600' cy='18' r='5' fill='#5b967f'/></svg></div><div class='chart-labels'><span>Day 1</span><span>Day 6</span><span>Day 12</span><span>Day 18</span></div><div class='chart-stats'><div><strong>42 → ${s.score}</strong><span>Sample starting point → now</span></div><div><strong>${s.checks}/${s.days}</strong><span>Check-ins this week</span></div></div>`:`<div class='empty'>${icon('chart')}<h3>Your story is just beginning.</h3><p>${s.forming?'Complete your first check-in to establish a starting point.':'You have your first data point. More daily check-ins will help surface useful patterns.'}</p>${button('Go to my day','go-today','outline')}</div>`}</section><section class='card'><h2>What’s behind your score</h2><p class='helper' style='margin-top:10px'>${state.mode==='sample'?'Illustrative activity plus your demo changes.':'Your activity in this browser.'}</p>${[['Promises kept',s.planned?Math.round(s.done/s.planned*100):0,`${s.done} / ${s.planned} actions`],['Showing up',Math.round(s.checks/s.days*100),`${s.checks} / ${s.days} days`],['Self-reported alignment',s.rating*20,`${s.rating} / 5`]].map(([label,value,note])=>`<div class='metric-row'><span>${label}</span><strong>${note}</strong></div><div class='bar'><span style='width:${value}%'></span></div>`).join('')}<p class='helper' style='margin-top:26px'>A feedback tool for your behaviors. It is not a measure of your worth or a validated assessment.</p></section></div><div class='grid-2 wide-spaced'><section class='insight-full'><div class='insight-label'>${icon('spark')} AN EXPERIMENT TO TRY</div><h3>Make the first step easier.</h3><p>Could tomorrow’s most meaningful action take just 10 minutes? Lower the starting line, keep the intention, and see what happens.</p><button class='text-button' style='margin-top:18px' data-action='add-action'>Turn this into a small promise ${icon('arrow')}</button></section><section class='card'><h2>Progress in every part of life</h2>${state.goals.map(g=>`<div class='metric-row'><span>${esc(g.title)}</span><strong>${g.progress}%</strong></div><div class='bar'><span style='width:${g.progress}%'></span></div>`).join('')}</section></div>`;}
function renderJournal(){const sampleEntries=state.mode==='sample'?[{id:'sample1',date:'A sample from yesterday',title:'Progress doesn’t have to be loud.',text:'I protected thirty minutes for my own work today. It wasn’t a huge breakthrough, but I followed through. I am starting to trust the small promises.',value:'Consistency'},{id:'sample2',date:'A sample from earlier this week',title:'Making space for what matters.',text:'I noticed how much better I felt after taking a walk before opening my inbox. Tomorrow, I want to create that space again.',value:'Well-being'}]:[];const entries=[...state.entries,...sampleEntries];return `${titleBlock('SPACE TO HEAR YOURSELF','A little pause. A little perspective.','Notice what matters. Write it down. Let it guide your next step.',button('Write a reflection','new-reflection','primary','edit'))}<div class='grid-2'><section class='card' style='padding:0'>${entries.length?entries.map(e=>`<article class='journal-entry'><div class='journal-date'>${esc(e.date)}</div><h3>${esc(e.title)}</h3><p>${esc(e.text)}</p>${e.value?`<span class='tag teal' style='margin-top:15px'>${esc(e.value)}</span>`:''}</article>`).join(''):`<div class='empty'>${icon('book')}<h3>Your words belong here.</h3><p>Your first reflection doesn’t need to be profound. Start with what’s on your mind.</p>${button('Write my first reflection','new-reflection','outline','edit')}</div>`}</section><div><section class='insight-card'><div class='insight-label'>${icon('spark')} A PROMPT FOR TODAY</div><h3>What did you do today that your future self would thank you for?</h3><p>There is no perfect answer. A small, honest moment is enough.</p><button class='text-button' data-action='new-reflection'>Take a moment to reflect ${icon('arrow')}</button></section><p class='helper' style='margin-top:20px'>${icon('shield').replace("class='icon'","class='icon' style='width:12px;height:12px;vertical-align:middle'")} Reflections stay in this browser in the prototype. Use illustrative content when presenting.</p></div></div>`;}
function renderCircle(){return `${titleBlock('GROW TOGETHER','You don’t have to become alone.','A small, consistent circle. Shared intentions. Real encouragement.',`<span class='journey-pill'>${icon('users')}Founding circle · Sample</span>`)}<div class='grid-2'><section class='card'><div class='section-heading'><h2>The wins, the wobbles, the work</h2><span class='tag slate'>DEMO FEED</span></div><p class='helper' style='margin-bottom:16px'>Practice sharing a win or asking for support. Posts are only visible in this browser.</p><label for='circle-post' class='form-label'>What’s one thing you’re proud of today?</label><textarea id='circle-post' class='post-box' placeholder='Even the smallest step counts…' maxlength='1000'></textarea><div style='text-align:right;margin:10px 0 22px'>${button('Share with my demo circle','share-post','primary','plus')}</div>${state.posts.map(p=>feedPost('You','A moment ago',p.text,p.id)).join('')}${feedPost('Jordan Lee','Sample member · 2 hours ago','I finally sent the proposal I had been overthinking. Today’s promise was just to write the first paragraph. The rest followed.','post1')}${feedPost('Aisha Scott','Sample member · 4 hours ago','A busy week got in the way. Today, I’m restarting with a ten-minute walk. Grateful for a place where starting again counts.','post2')}</section><div class='stack' style='align-content:start'><section class='card'><div class='eyebrow' style='color:#939eac'>YOUR NEXT GATHERING · SAMPLE</div><h2 style='font-family:var(--serif);font-size:29px;font-weight:500;margin:14px 0'>The weekly reset.</h2><p class='helper'>Pause with your circle. Celebrate one win, work through one obstacle, and choose next week’s promise.</p><div class='setting-row'><span class='helper'>${icon('calendar')} Sunday · 6:00 PM CT</span></div><div class='setting-row'><span class='helper'>${icon('clock')} 45 minutes · Virtual</span></div><div class='members'>${avatars()}<p>6 sample members · Hosted by Chris</p></div>${button(state.rsvp?'You’re on the demo list ✓':'Reserve my place','rsvp','primary','arrow')}<p class='helper' style='font-size:9px;margin-top:12px'>Preview RSVP only. No event booking or invitation is sent.</p></section><section class='insight-full'><h3>Come as you are.</h3><p>Share only what feels right. Listen with care. Celebrate effort, not comparison. Your private reflections stay yours.</p></section></div></div>`;}
function feedPost(name,time,text,id){return `<article class='feed-post'><div class='members'><span class='avatar'>${esc(name.split(' ').map(n=>n[0]).join(''))}</span><div><strong>${esc(name)}</strong><p style='margin:0;font-size:9px'>${time}</p></div></div><p>${esc(text)}</p><button class='text-button' data-action='cheer' data-id='${id}' aria-pressed='${state.cheers.includes(id)}'>${icon('heart')}${state.cheers.includes(id)?'Encouragement added':'Send encouragement'}</button></article>`;}
function renderSettings(){return `${titleBlock('MAKE THIS SPACE YOURS','A rhythm that works for you.','Your preferences, your data, your journey.')}<div class='grid-2'><div class='stack'><section class='card'><h2>Your profile</h2><form id='settings-form' style='margin-top:22px'><div class='form-field'><label for='settings-name'>Full name</label><input id='settings-name' name='name' value='${esc(state.name)}' maxlength='70' required></div>${button('Save profile','save-settings','primary','check')}</form></section><section class='card'><h2>Your reminders</h2><p class='helper' style='margin-top:8px'>Preferences preview. This prototype does not send notifications.</p>${[['daily','Daily check-in','A gentle reminder to return to yourself.'],['weekly','Weekly circle','Make room for your weekly reset.']].map(([key,title,desc])=>`<div class='setting-row'><div><h3>${title}</h3><p>${desc}</p></div><button class='toggle ${state.notifications[key]?'on':''}' role='switch' aria-checked='${state.notifications[key]}' aria-label='${title} reminder' data-action='toggle-notification' data-id='${key}'></button></div>`).join('')}</section></div><div class='stack' style='align-content:start'><section class='card'><h2>Your browser data</h2><p class='helper' style='margin:13px 0 20px'>Your changes are stored on this device. Export them for your notes, or reset to the sample journey for your next presentation.</p><div style='display:flex;gap:10px;flex-wrap:wrap'>${button('Export my data','export','outline','download')}${button('Reset demo','reset','outline','route')}</div></section><section class='card'><div class='insight-label'>${icon('shield')} A PROTOTYPE WITH CLEAR BOUNDARIES</div><p class='helper' style='margin:15px 0'>This is an interactive product concept. Accounts, subscriptions, live AI, secure cloud storage, and real community services belong to a subsequent production build.</p><button class='text-button' data-page='founder'>See the build priorities ${icon('arrow')}</button></section>${button('Explore the welcome page','welcome','outline','logout')}</div></div>`;}
function renderHelp(){return `${titleBlock('A LITTLE GUIDANCE','A good place to find your footing.','Everything you need to explore this preview.')}<div class='grid-2'><section class='card'><h2>Questions, answered</h2>${[['What is the 90-Day Greatness Journey?','A personal growth and accountability experience centered on one meaningful goal, daily reflection and weekly virtual growth sessions. This prototype explores how the future platform could support that journey.'],['How does my Greatnessly Score work?','The prototype combines kept daily actions (50%), check-in participation (30%), and self-reported alignment (20%). It is an experimental behavior indicator, not a validated measure of transformation. Open the score breakdown from My day for the inputs.'],['What happens if I miss a day?','You start again with a small promise. Your past effort remains visible, and the design avoids a streak that wipes out your progress.'],['Is the coach using live AI?','No. Reflection prompts and suggestions in this preview use curated examples and simple local rules. A real AI service would require separate integration, consent and evaluation.'],['Is my circle real?','The circle, members, posts and weekly session are examples. Your interactions stay in your browser and do not notify anyone.']].map(([q,a])=>`<details class='faq'><summary>${q}</summary><p>${a}</p></details>`).join('')}</section><section class='card' style='align-self:start'><div class='eyebrow' style='color:#a0aab7'>THE FOUNDING JOURNEY</div><h2 style='font-family:var(--serif);font-size:29px;font-weight:500;margin:14px 0'>Curious about joining?</h2><p class='helper' style='margin-bottom:23px'>Chris is gathering interest for the founding community. Learn more and register your interest through his original form.</p><a class='btn btn-primary' href='https://forms.gle/2nsg7yaX64QLWv2z6' target='_blank' rel='noopener noreferrer'>Register my interest ${icon('arrow')}</a><p class='helper' style='margin-top:20px'>Questions for Chris: <a href='tel:+17737040493' style='color:var(--navy)'>(773) 704-0493</a></p></section></div>`;}
function renderFounder(){return `${titleBlock('THE THINKING BEHIND THE EXPERIENCE','A focused beginning. A bigger possibility.','Product direction for the founding Greatnessly cohort.')}<section class='card profile-vision'><div class='eyebrow' style='color:#6e9185'>OUR PRODUCT THESIS · A HYPOTHESIS TO TEST</div><blockquote style='font-size:29px'>Help an ambitious person turn one future-self intention into daily evidence of change—with a circle that helps them return.</blockquote><p class='helper'>Start with professionals and independent business builders who know what they want, but struggle to follow through while balancing a busy life. Chris’s facilitated cohort is the starting point.</p></section><div class='section-heading wide-spaced'><h2>Learn from the category. Build a coherent journey.</h2></div><div class='research-grid'>${[['Fabulous','Guided routines, habit building, coaching and community.','Borrow progressive guidance. Explore a 90-day arc anchored to the member’s chosen identity and measurable outcome.','https://www.thefabulous.co/'],['Coach.me','Habit tracking, community encouragement and individual habit coaches.','Borrow human accountability. Test a stable small-circle format with a weekly reset led by a facilitator.','https://coach.me/'],['Rosebud','AI journaling, remembered context, goals and weekly reflection reports.','Borrow contextual reflection. Tie each useful insight to a small promise and revisit it at the next check-in.','https://www.rosebud.app/'],['Focusmate','Scheduled virtual coworking with shared intentions and end-of-session check-ins.','Borrow an explicit commitment ritual. Connect daily promises to a longer personal growth journey.','https://www.focusmate.com/']].map(([name,strength,idea,url])=>`<section class='card research-card'><h3>${name}</h3><p><strong>Verified emphasis:</strong> ${strength}</p><p><strong>Design opportunity:</strong> ${idea}</p><a href='${url}' target='_blank' rel='noopener noreferrer'>Official product source ↗</a></section>`).join('')}</div><p class='helper' style='margin-top:15px'>Reviewed October 17, 2026. Opportunities are hypotheses, not claims that competitors lack these capabilities. Greatnessly’s differentiation must be tested with participants.</p><div class='section-heading wide-spaced'><h2>Build the loop before expanding the platform.</h2></div><div class='card'><table class='print-table'><thead><tr><th>Now · Prove value</th><th>Next · Make it real</th><th>Later · Earn the complexity</th></tr></thead><tbody><tr><td>Future-self setup<br>One outcome + daily promise<br>Daily reflection<br>Transparent activity feedback<br>Weekly circle + reset</td><td>Secure sign-in and recovery<br>Owner-scoped database + RLS<br>Real cohort facilitation<br>Evaluated, opt-in AI guidance<br>Reliable reminders and deletion</td><td>Subscriptions and pricing<br>Additional life-domain programs<br>Calendar integrations<br>Advanced facilitator tools<br>Broader community discovery</td></tr></tbody></table><p class='helper'>Primary pilot outcome: participants return, keep meaningful promises, and report progress toward their chosen goal. Validate willingness to pay before choosing pricing tiers.</p></div><div class='scope-label'>This concept uses illustrative member data and local browser storage. It demonstrates the experience; production authentication, authorization, RLS, real AI, billing and admin operations have not been implemented.</div><div class='section-heading'><h2>A four-minute founder walkthrough</h2></div><div class='grid-3'><section class='card'><div class='eyebrow muted'>01 · START WITH IDENTITY</div><h3 style='margin:12px 0'>Become someone, then do something.</h3><p class='helper'>Show the welcome page and the three-step blueprint. Pick one goal and one small promise.</p><button class='text-button' data-action='welcome' style='margin-top:18px'>Open welcome page ${icon('arrow')}</button></section><section class='card'><div class='eyebrow muted'>02 · EXPERIENCE THE LOOP</div><h3 style='margin:12px 0'>A little value, every day.</h3><p class='helper'>Keep a promise, complete a check-in, inspect the score, and turn reflection into an action.</p><button class='text-button' data-page='today' style='margin-top:18px'>Explore My day ${icon('arrow')}</button></section><section class='card'><div class='eyebrow muted'>03 · RETURN WITH SUPPORT</div><h3 style='margin:12px 0'>Build a reason to come back.</h3><p class='helper'>Explore the weekly reset and discuss how Chris would facilitate the founding circle.</p><button class='text-button' data-page='circle' style='margin-top:18px'>Meet the sample circle ${icon('arrow')}</button></section></div>`;}
function renderLanding(){
  $('#app').innerHTML=`<div class='landing landing-v2'>
    <header class='landing-nav'><a href='#welcome' data-page='welcome' aria-label='Greatnessly home'>${brand()}</a><nav class='landing-links'><a href='#how-it-works'>The experience</a><button class='text-button' data-page='founder'>Our approach</button><div class='theme-control-slot'></div>${button('Explore the demo','go-today','outline','arrow')}</nav></header>
    <main id='main' class='welcome-main'>
      <section class='welcome-hero'>
        <div class='welcome-copy'><div class='welcome-kicker'><span class='live-spark'></span> YOUR NEXT CHAPTER STARTS HERE</div><h1>Become the person<br>you keep <em>imagining.</em><svg class='handwritten-line' viewBox='0 0 360 20' aria-hidden='true'><path d='M4 13C100 0 220 4 351 10M33 18C140 7 230 9 324 15'/></svg></h1><p>Big intentions. Small daily promises. A little support along the way. Make the next 90 days a meaningful chapter in your story.</p><div class='welcome-actions'>${button('Begin my 90-day journey','new-journey','mint','arrow')}<button class='welcome-demo' data-action='go-today'><span class='play-disc'>${icon('arrow')}</span>Take a look inside</button></div><div class='welcome-note'>${icon('clock')} A two-minute beginning. A direction that’s yours.</div></div>
        <div class='chapter-visual' aria-label='Interactive example of a future-self goal'>
          <div class='chapter-photo'></div><div class='orbital orbital-one'></div><div class='orbital orbital-two'></div><span class='orbit-point point-one'></span><span class='orbit-point point-two'></span><div class='floating-label label-north'>${icon('compass')} A little more aligned.</div><div class='chapter-preview-card'><div class='preview-card-top'><span class='eyebrow'>YOUR FUTURE, A LITTLE CLOSER</span><span class='preview-star'>${icon('spark')}</span></div><div class='chapter-tabs' role='group' aria-label='Choose an example direction'>${['Career','Well-being','Connection'].map((v,i)=>`<button class='chapter-tab ${i===chapterChoice?'selected':''}' data-action='preview-chapter' data-value='${i}' aria-pressed='${i===chapterChoice}'>${v}</button>`).join('')}</div><div class='preview-identity'><span class='preview-avatar'>${icon('leaf')}</span><div><span class='eyebrow'>I AM BECOMING</span><h2 id='preview-identity'>${chapterExamples[chapterChoice].identity}</h2></div></div><div class='preview-goal'><span class='eyebrow'>MY 90-DAY OUTCOME</span><p id='preview-goal'>${chapterExamples[chapterChoice].goal}</p><div class='preview-goal-bar'><span></span></div></div><div class='preview-promise'><div class='promise-label'>ONE SMALL PROMISE TODAY</div><button class='preview-check ${previewPromiseKept?'is-kept':''}' data-action='preview-promise' aria-pressed='${previewPromiseKept}'><span class='preview-checkbox'>${previewPromiseKept?icon('check'):''}</span><span id='preview-promise'>${chapterExamples[chapterChoice].promise}</span><span class='preview-minutes'>10 min</span></button></div><div class='preview-feedback' id='preview-feedback' role='status'>${previewPromiseKept?'That’s what showing up feels like.':'Try keeping this small promise. Click the circle.'}</div></div><div class='floating-label label-growth'>${icon('up')} Small steps. A different direction.</div><div class='chapter-caption'>ILLUSTRATIVE PREVIEW · YOUR OWN JOURNEY WILL BE UNIQUE</div>
        </div>
      </section>
      <section class='welcome-proof' aria-label='The journey at a glance'><div><strong>90</strong><span>days of intentional growth</span></div><span class='proof-divider'></span><div><strong>01</strong><span>meaningful goal to begin</span></div><span class='proof-divider'></span><div class='proof-human'>${avatars()}<span>A small circle.<br><strong>A shared commitment.</strong></span></div></section>
      <section class='rhythm-section${rhythmMotionPaused?' motion-paused':''}' id='how-it-works'><div class='editorial-heading'><div><div class='eyebrow'>LESS OVERWHELM. MORE ALIGNMENT.</div><h2>A rhythm for<br><em>real life.</em></h2></div><p>You don’t need to reinvent your whole life overnight. Just make a little space for who you want to become.</p></div><div class='rhythm-grid'><article class='rhythm-card rhythm-vision'><div class='rhythm-top'><span>01 / FIND YOUR DIRECTION</span>${icon('compass')}</div><div class='vision-art' aria-hidden='true'><span></span><span></span><span></span><b>${icon('spark')}</b></div><h3>Know your north star.</h3><p>A future-self blueprint connects your vision and values to one outcome that matters to you.</p><button class='text-button' data-action='new-journey'>Picture my future self ${icon('arrow')}</button></article><article class='rhythm-card rhythm-action'><div class='rhythm-top'><span>02 / SHOW UP, SIMPLY</span>${icon('check')}</div><div class='mini-promises' aria-hidden='true'><span>${icon('check')} One intentional action.</span><span>${icon('check')} A moment to reflect.</span><span class='promise-active'>${icon('plus')} A little more momentum.</span></div><h3>Make today count.</h3><p>Choose a small promise, protect a little time, and close the day with an honest check-in.</p><button class='text-button' data-action='go-today'>Explore a day in the journey ${icon('arrow')}</button></article><article class='rhythm-card rhythm-circle'><div class='rhythm-top'><span>03 / GROW TOGETHER</span>${icon('users')}</div><div class='circle-art' aria-hidden='true'><span class='circle-link'></span><span class='circle-person circle-person-one'>JL</span><span class='circle-person circle-person-two'>AS</span><span class='circle-person circle-person-three'>YOU</span></div><h3>Find your people.</h3><p>Celebrate a win. Work through a wobble. Return to your intention with a consistent weekly circle.</p><button class='text-button' data-page='circle'>Meet the sample circle ${icon('arrow')}</button></article></div><div class='rhythm-motion-tools'><button class='rhythm-motion-toggle' data-action='toggle-rhythm-motion' aria-pressed='${rhythmMotionPaused}'>${rhythmMotionPaused?'Play animations':'Pause animations'}</button></div></section>
      <section class='chapter-explorer'><div class='chapter-explorer-copy'><div class='eyebrow'>ONE CHAPTER. THREE SEASONS.</div><h2>You don’t need the whole path.<br><em>Just your next step.</em></h2><p>Explore how the journey unfolds. Your pace, priorities, and progress will be your own.</p><div class='journey-scrub'><div class='scrub-label'><label for='journey-preview'>Explore the 90-day journey</label><output id='journey-preview-day' for='journey-preview'>Day 18</output></div><input type='range' id='journey-preview' min='1' max='90' value='18'><div class='scrub-marks'><span>Day 01</span><span>Day 45</span><span>Day 90</span></div></div></div><div class='season-card' data-season='0'><div class='season-card-top'><span class='tag'>DAYS <span id='season-range'>01—30</span></span><span id='season-index'>01</span></div><div class='season-mark'>${icon('leaf')}</div><h3 id='season-title'>Build the roots.</h3><p id='season-copy'>Clarify your vision. Choose a meaningful goal. Find a small daily rhythm you can return to.</p><div class='season-progress'><span></span><span></span><span></span></div></div></section>
      <section class='founding-invitation'><div class='invitation-orbit' aria-hidden='true'></div><div class='eyebrow'>THE FOUNDING COMMUNITY</div><h2>Some beginnings<br>are better <em>together.</em></h2><p>Chris is bringing together ambitious people ready to take intentional action. Experience the framework and help shape the future of Greatnessly.</p><a class='btn btn-mint' href='https://forms.gle/2nsg7yaX64QLWv2z6' target='_blank' rel='noopener noreferrer'>Register my interest ${icon('arrow')}</a><span class='invitation-note'>Cohort dates and pricing will be confirmed by the founder.</span></section>
    </main><footer class='landing-footer'><span>greatnessly. &nbsp; A little more aligned. A little more you.</span><button data-action='demo-info'>Interactive product concept ${icon('arrow')}</button></footer></div>`;
}

function showModal(type){lastFocus=document.activeElement;modalType=type;modalStep=0;draft={};if(type==='checkin'){if(state.checkin){draft={...state.checkin};modalStep=3;}else draft={energy:3,gratitude:'',reflection:'',alignment:3,promise:state.tasks.find(t=>!t.done)?.title||''};}if(type==='setup'){draft={name:'',vision:'',values:[],goal:'',category:'Career',identity:'',growth:'',promise:''};}if(type==='edit-profile'){draft={...state,values:[...state.values]};}drawModal();document.body.style.overflow='hidden';}
function modalHeader(eyebrow,title,intro){return `<div class='eyebrow'>${eyebrow}</div><h2 id='modal-title'>${title}</h2><p class='modal-intro'>${intro}</p>`;}
function stepper(step){return `<div class='stepper' aria-label='Step ${step+1} of 3'>${[0,1,2].map(i=>`<span class='${i<=step?'active':''}'></span>`).join('')}</div>`;}
function field(label,id,value='',placeholder='',kind='input'){return `<div class='form-field'><label for='${id}'>${label}</label><${kind} id='${id}' name='${id}' ${kind==='input'?`value='${esc(value)}'`:''} placeholder='${placeholder}' maxlength='${kind==='textarea'?1500:200}'>${kind==='textarea'?esc(value):''}${kind==='textarea'?'</textarea>':''}</div>`;}
function drawModal(){let content='';let wide=false;
if(modalType==='checkin'){
if(modalStep===0)content=modalHeader('YOUR DAILY ALIGNMENT · 1 OF 3','First, meet yourself where you are.','No right answer. Just a little space to notice how you’re arriving today.')+stepper(0)+`<span class='form-label'>How is your energy?</span><div class='energy-grid'>${['Running low','A little tired','Steady','Feeling good','Energized'].map((label,i)=>`<button class='energy ${draft.energy===i+1?'selected':''}' data-action='energy' data-value='${i+1}' aria-pressed='${draft.energy===i+1}'>${icon(['moon','cloud','leaf','smile','sun'][i])}<span>${label}</span></button>`).join('')}</div>`+field('One thing I’m grateful for','gratitude',draft.gratitude,'A small moment, a person, a possibility…','textarea')+`<div class='modal-footer'><span>Honest is better than perfect.</span>${button('A little reflection','checkin-next')}</div>`;
if(modalStep===1)content=modalHeader('YOUR DAILY ALIGNMENT · 2 OF 3','Notice the person you practiced being.','Think about one action or choice. What did it tell you about your direction?')+stepper(1)+`<div class='prompt-box'><div class='eyebrow'>YOUR NORTH STAR</div>${esc(state.vision)}</div>`+field('What moved me closer—or got in my way?','reflection',draft.reflection,'Today, I noticed…','textarea')+`<div class='form-field'><label for='alignment'>How aligned did my choices feel? <span id='alignment-value'>${draft.alignment}/5</span></label><input type='range' id='alignment' min='1' max='5' value='${draft.alignment}'><small>1 · Far from my intention &nbsp;→&nbsp; 5 · Closely aligned</small></div><div class='error-text' id='form-error'></div><div class='modal-footer'><button class='text-button' data-action='checkin-back'>Back</button>${button('Choose my next step','checkin-next')}</div>`;
if(modalStep===2)content=modalHeader('YOUR DAILY ALIGNMENT · 3 OF 3','A small promise to your future self.','What is one doable action you want to return to? Make it specific and kind to your real life.')+stepper(2)+field('My next small promise','promise',draft.promise,'Spend 10 minutes outlining my idea')+`<div class='prompt-box'><div class='eyebrow'>A GENTLE SUGGESTION · PREVIEW GUIDANCE</div>${draft.energy<3?'Your energy is low. Could this take just five minutes? A smaller action still counts.':'Make the first step easy to start. A clear action and a little protected time can be enough.'}</div><p class='helper'>Your reflection stays in this browser. It is not shared with your circle.</p><div class='error-text' id='form-error'></div><div class='modal-footer'><button class='text-button' data-action='checkin-back'>Back</button>${button('Complete my check-in','save-checkin','primary','check')}</div>`;
if(modalStep===3)content=`<div class='success-icon'>${icon('check')}</div>`+modalHeader('A PROMISE TO YOURSELF, KEPT','You showed up. That matters.','Take this moment with you. Small, honest check-ins build a clearer picture over time.')+`<div class='saved-summary'><strong>Your next small promise</strong><p>${esc(draft.promise)}</p></div><p class='helper'>${draft.reflection?esc(draft.reflection):'One intentional step is a good place to begin.'}</p><div class='modal-footer'><span>Check-in saved for today.</span>${button('Back to my day','close-modal')}</div>`;
}
if(modalType==='setup'){
if(modalStep===0)content=modalHeader('A NEW CHAPTER · 1 OF 3','Who are you becoming?','You don’t need a perfect plan. Let’s start with a direction that feels like you.')+stepper(0)+field('What should we call you?','setup-name',draft.name,'Your name')+field('In 90 days, I want to be someone who…','setup-vision',draft.vision,'Creates meaningful work and has energy for the people I love.','textarea')+`<div class='prompt-box'><div class='eyebrow'>A LITTLE INSPIRATION</div><button class='text-button' data-action='example-vision'>${icon('spark')}Help me find the words</button></div><div class='error-text' id='form-error'></div><div class='modal-footer'><span>About 2 minutes. Always editable.</span>${button('Find my north star','setup-next')}</div>`;
if(modalStep===1)content=modalHeader('A NEW CHAPTER · 2 OF 3','Choose what matters most.','Let your values guide the way. Then give this chapter one meaningful outcome.')+stepper(1)+`<span class='form-label'>Choose up to 3 values</span><div class='choice-grid' style='margin-bottom:22px'>${['Purpose','Growth','Well-being','Connection','Courage','Freedom'].map(v=>`<button class='choice ${draft.values.includes(v)?'selected':''}' data-action='value' data-value='${v}' aria-pressed='${draft.values.includes(v)}'>${draft.values.includes(v)?icon('check'):''}${v}</button>`).join('')}</div>`+field('One goal that would make these 90 days meaningful','setup-goal',draft.goal,'Launch my consulting practice')+`<div class='form-field'><label for='setup-category'>A part of my life</label><select id='setup-category'>${['Career','Health','Relationships','Financial','Personal'].map(c=>`<option ${draft.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class='error-text' id='form-error'></div><div class='modal-footer'><button class='text-button' data-action='setup-back'>Back</button>${button('Make it part of today','setup-next')}</div>`;
if(modalStep===2)content=modalHeader('A NEW CHAPTER · 3 OF 3','Give your future a first step.','The first promise is small on purpose. You’re creating a place to begin, not a perfect version of yourself.')+stepper(2)+field('I’m practicing being…','setup-identity',draft.identity,'Intentional, consistent, courageous')+field('One area I want to grow in','setup-growth',draft.growth,'Following through, even when life gets busy')+field('My first small promise','setup-promise',draft.promise,'Spend 10 minutes on the first step')+`<div class='prompt-box'><div class='eyebrow'>SUGGESTION · CURATED PREVIEW</div><button class='text-button' data-action='example-action'>${icon('spark')}Suggest a first step for my goal</button></div><div class='error-text' id='form-error'></div><div class='modal-footer'><button class='text-button' data-action='setup-back'>Back</button>${button('Create my journey','save-setup','primary','leaf')}</div>`;
}
if(modalType==='edit-profile')content=modalHeader('YOUR BLUEPRINT','Your direction can grow with you.','Refine what matters. You can return here whenever your perspective changes.')+field('My future self','edit-vision',draft.vision,'Describe who you’re becoming','textarea')+field('My values · separate with commas','edit-values',draft.values.join(', '),'Purpose, growth, well-being')+field('My desired identity','edit-identity',draft.identity,'Intentional, courageous, consistent')+field('My growth area','edit-growth',draft.growth,'Where I want to grow','textarea')+`<div class='error-text' id='form-error'></div><div class='modal-footer'><span>Always a work in progress.</span>${button('Save my blueprint','save-profile','primary','check')}</div>`;
if(modalType==='add-goal')content=modalHeader('MAKE ROOM FOR A POSSIBILITY','What would make these 90 days meaningful?','Choose an outcome you can recognize, and a reason that makes it worth showing up for.')+field('My goal','goal-title','','For example: Have my first 3 paying clients')+`<div class='form-field'><label for='goal-category'>Life area</label><select id='goal-category'>${['Career','Health','Relationships','Financial','Personal'].map(c=>`<option>${c}</option>`).join('')}</select></div>`+field('Why it matters to my future self','goal-why','','Build a business that supports my values','textarea')+field('The first milestone','goal-milestone','','Define one clear offer')+`<div class='error-text' id='form-error'></div><div class='modal-footer'><button class='text-button' data-action='close-modal'>Cancel</button>${button('Create my goal','save-goal','primary','plus')}</div>`;
if(modalType==='add-action')content=modalHeader('SMALL ENOUGH TO START','One promise. A little momentum.','Make it a concrete action you can finish today.')+field('My small promise','action-title',draft.action||'','Write the first paragraph of my proposal')+`<div class='form-field'><label for='action-goal'>Connect it to my goal</label><select id='action-goal'>${state.goals.map(g=>`<option value='${esc(g.id)}'>${esc(g.title)}</option>`).join('')}<option value='personal'>A personal intention</option></select></div><div class='form-field'><label for='action-mins'>Time I want to protect · minutes</label><input id='action-mins' type='number' min='1' max='240' value='10'></div><div class='error-text' id='form-error'></div><div class='modal-footer'><button class='text-button' data-action='close-modal'>Cancel</button>${button('Add to my day','save-action','primary','plus')}</div>`;
if(modalType==='goal-detail'){const g=state.goals.find(x=>x.id===draft.id);if(!g)return;content=modalHeader(`${esc(g.category)} · MY 90-DAY OUTCOME`,esc(g.title),esc(g.why))+`<div class='bar'><span style='width:${g.progress}%'></span></div><div class='metric-row'><span>Milestones completed</span><strong>${g.progress}%</strong></div><div class='goal-details'><h3>My path forward</h3><ul>${g.milestones.map(m=>`<li>${esc(m)}</li>`).join('')}</ul></div><div class='form-field' style='margin-top:25px'><label for='goal-progress'>Update my milestone progress</label><input type='range' id='goal-progress' min='0' max='100' value='${g.progress}' step='5'><small id='goal-progress-label'>${g.progress}%</small></div><div class='modal-footer'>${button('Add a daily action','goal-add-action','outline','plus')}${button('Save progress','save-progress','primary','check')}</div>`;}
if(modalType==='new-reflection')content=modalHeader('A MOMENT, JUST FOR YOU','What’s on your mind?','Write freely, or start with this: what would your future self thank you for today?')+field('A title for this moment','journal-title','','A small win worth remembering')+field('My reflection','journal-text','','Today, I noticed…','textarea')+`<div class='prompt-box'><div class='eyebrow'>REFLECTION GUIDE · NO LIVE AI</div><button class='text-button' data-action='journal-prompt'>${icon('spark')}Give me a different prompt</button><p id='journal-prompt-text'></p></div><p class='helper'>Only stored in this browser. Nothing is sent to your circle.</p><div class='error-text' id='form-error'></div><div class='modal-footer'><button class='text-button' data-action='close-modal'>Cancel</button>${button('Save reflection','save-reflection','primary','check')}</div>`;
if(modalType==='reflection-guide')content=modalHeader('YOUR INNER COMPASS · CURATED GUIDANCE','Make room for your most meaningful work.','A useful reflection ends with a next step you can actually take.')+`<div class='prompt-box'>What is the smallest version of your most important action? Could it happen before you open your inbox?</div><p class='helper'>Try a 10-minute block. Write one paragraph, make one connection, or prepare one thing that makes tomorrow easier. Notice whether protecting that little bit of time changes how the day feels.</p><div class='scope-label'>This is a curated reflection prompt. The prototype does not analyze your journal with live AI.</div><div class='modal-footer'><button class='text-button' data-action='close-modal'>Just sit with this</button>${button('Make a small promise','guide-to-action','primary','plus')}</div>`;
if(modalType==='score-info'){const s=scoreData();content=modalHeader('UNDERSTAND YOUR FEEDBACK','Progress you can make sense of.','The Greatnessly Score is an experimental behavior indicator. It reflects participation and self-reported alignment, not personal worth.')+`<div class='score-breakdown'><div>Promises kept <strong>50% weight</strong><p>${s.done} completed / ${s.planned} planned daily actions ${state.mode==='sample'?'over a sample 7-day window':''}.</p></div><div>Showing up <strong>30% weight</strong><p>${s.checks} check-ins / ${s.days} ${s.days===1?'journey day':'days'}.</p></div><div>Self-reported alignment <strong>20% weight</strong><p>${s.rating}/5 alignment rating${state.mode==='sample'&&!state.checkin?' from illustrative data':''}. Your check-in updates this input.</p></div></div><p class='helper'>${s.forming?'Your baseline is forming. Complete a check-in to display your starting score.':`Current calculation: ${s.planned?((s.done/s.planned)*50).toFixed(1):0} + ${(s.checks/s.days*30).toFixed(1)} + ${(s.rating/5*20).toFixed(1)} = ${s.score}/100, rounded.`} The weights are a product hypothesis to evaluate with participants. This is not a validated growth assessment.</p><div class='modal-footer'><span>${state.mode==='sample'?'Sample data + your demo interactions':'Your current browser activity'}</span>${button('Got it','close-modal')}</div>`;}
if(modalType==='rsvp')content=modalHeader('BETTER, TOGETHER · SAMPLE SESSION','The weekly reset.','Sunday · 6:00 PM Central · 45 minutes · Virtual')+`<div class='saved-summary'><strong>A little structure for a fresh week.</strong><p>10 min · One win worth noticing<br>20 min · One obstacle, shared perspective<br>15 min · One clear promise for the week ahead</p></div><p class='helper'>This is a session concept for Chris’s founding cohort. Your RSVP is saved only in this browser. No calendar invitation or meeting access is sent.</p><div class='modal-footer'><button class='text-button' data-page='circle' data-action='close-modal'>Explore my circle</button>${button(state.rsvp?'Remove demo RSVP':'Reserve in this demo','confirm-rsvp','primary',state.rsvp?'close':'check')}</div>`;
if(modalType==='notifications')content=modalHeader('YOUR GENTLE REMINDERS','A little nudge toward what matters.','Sample notifications for your journey.')+`<div class='saved-summary'><strong>${state.checkin?'Your check-in is complete ✓':'Your daily check-in is waiting.'}</strong><p>Two minutes to pause, find perspective, and choose your next step.</p></div><div class='saved-summary'><strong>Your circle’s weekly reset</strong><p>Sample session · Sunday, 6:00 PM CT. Make room for a fresh week.</p></div><p class='helper'>These are preview notifications. No reminders are being sent.</p><div class='modal-footer'>${button('My reminders','go-settings','outline','settings')}${button('Check in','open-checkin')}</div>`;
if(modalType==='demo-info')content=modalHeader('GREATNESSLY · INTERACTIVE PRODUCT CONCEPT','A glimpse of what’s possible.','Explore a future-self blueprint, daily promises, reflective check-ins and a supportive 90-day journey.')+`<div class='saved-summary'><strong>Designed to be tried.</strong><p>Complete actions, add goals, journal, update your blueprint and reserve a sample session. Your changes are saved in this browser.</p></div><p class='helper'>Maya’s journey, the circle, progress history and insights are illustrative. Guidance is curated, without a live AI service. This prototype has no production accounts, backend, billing or administrator access.</p><div class='modal-footer'>${button('The product story','product-story','outline','book')}${button('Start exploring','close-modal')}</div>`;
if(modalType==='reset')content=modalHeader('READY FOR ANOTHER WALKTHROUGH?','Return to the sample journey.','This clears the goals, reflections and preferences you’ve saved in this browser and restores Maya’s illustrative journey.')+`<p class='helper'>You can export your data in Settings before resetting.</p><div class='modal-footer'><button class='text-button' data-action='close-modal'>Keep my changes</button>${button('Reset this demo','confirm-reset','primary','route')}</div>`;
if(modalType==='new-journey')content=modalHeader('MAKE A NEW BEGINNING','Try your own 90-day journey.','The three-step setup replaces the current browser demo with your own blueprint and first promise.')+`<p class='helper'>Your current demo data will be replaced when you complete setup. Canceling keeps your existing journey.</p><div class='modal-footer'><button class='text-button' data-action='close-modal'>Keep exploring</button>${button('Let’s begin','start-setup','primary','leaf')}</div>`;
if(modalType==='journey-day'){const n=Number(draft.day);content=modalHeader(`DAY ${n} · ${state.mode==='sample'?'SAMPLE JOURNEY':'YOUR JOURNEY'}`,n===state.day?'Your next step is here.':n<state.day?'Every step leaves a little evidence.':'A possibility still ahead.',n===state.day?'Make today a little more aligned. A small promise and a moment of reflection are enough.':n<state.day?'Your earlier efforts stay part of the story, including the days you needed a pause.':'Focus on the day you’re in. Later steps in your journey will build on what you learn today.')+`<div class='prompt-box'>${n<state.day?'Weekly reflection: What helped you show up? What would make the next step easier?':n<=30?'Foundation · Clarify your direction and practice a daily rhythm.':n<=60?'Momentum · Notice what works and deepen your practice.':'Becoming · Celebrate the evidence and choose what comes next.'}</div><div class='modal-footer'><span>Keep becoming, one day at a time.</span>${button('Back to my day','go-today')}</div>`;}
$('#modal-root').innerHTML=`<div class='modal-backdrop'><section class='modal ${wide?'wide':''}' role='dialog' aria-modal='true' aria-labelledby='modal-title'><button class='icon-btn modal-close' data-action='close-modal' aria-label='Close dialog'>${icon('close')}</button>${content}</section></div>`;
requestAnimationFrame(()=>{const input=$('input:not([type=range]),textarea,select',$('#modal-root'));(input||$('.modal-close'))?.focus();});}
function closeModal(){if(modalType==='focus')stopFocusTimer();modalType=null;$('#modal-root').innerHTML='';document.body.style.overflow='';lastFocus?.isConnected&&lastFocus.focus();}
function error(text){const el=$('#form-error');if(el){el.textContent=text;el.scrollIntoView({block:'nearest'});}else toast(text);}
async function pending(btn,work){if(btn?.disabled)return;const old=btn?.innerHTML;if(btn){btn.disabled=true;btn.innerHTML=`<span class='spinner'></span> Saving…`;}await new Promise(r=>setTimeout(r,420));try{work();}catch(e){toast('Something didn’t save. Please try again.');console.error(e);}finally{if(btn?.isConnected){btn.disabled=false;btn.innerHTML=old;}}}
function captureSetup(){if(modalStep===0){draft.name=$('#setup-name').value.trim();draft.vision=$('#setup-vision').value.trim();}if(modalStep===1){draft.goal=$('#setup-goal').value.trim();draft.category=$('#setup-category').value;}if(modalStep===2){draft.identity=$('#setup-identity').value.trim();draft.growth=$('#setup-growth').value.trim();draft.promise=$('#setup-promise').value.trim();}}
function captureCheckin(){if(modalStep===0)draft.gratitude=$('#gratitude').value.trim();if(modalStep===1){draft.reflection=$('#reflection').value.trim();draft.alignment=Number($('#alignment').value);}if(modalStep===2)draft.promise=$('#promise').value.trim();}
function exportData(){const data=JSON.stringify(state,null,2),blob=new Blob([data],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='my-greatnessly-journey.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your browser journey has been exported.');}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action],[data-page]');if(!el)return;const action=el.dataset.action;const page=el.dataset.page;
if(page){e.preventDefault();if(modalType)closeModal();navigate(page);if(!action)return;}
if(action==='toggle-rhythm-motion'){
  rhythmMotionPaused=!rhythmMotionPaused;
  $('#how-it-works')?.classList.toggle('motion-paused',rhythmMotionPaused);
  el.setAttribute('aria-pressed',String(rhythmMotionPaused));
  el.textContent=rhythmMotionPaused?'Play animations':'Pause animations';
}
if(action==='menu'){$('.sidebar').classList.add('open');$('.mobile-shade').classList.add('open');$('.mobile-menu').setAttribute('aria-expanded','true');}
if(action==='close-menu'){$('.sidebar').classList.remove('open');$('.mobile-shade').classList.remove('open');$('.mobile-menu')?.setAttribute('aria-expanded','false');}
if(action==='close-modal')closeModal();
if(['checkin','score-info','reflection-guide','add-goal','add-action','new-reflection','rsvp','notifications','demo-info','reset','new-journey','edit-profile'].includes(action))showModal(action);
if(action==='welcome')navigate('welcome');if(action==='go-today'){closeModal();navigate('today');}if(action==='go-settings'){closeModal();navigate('settings');}if(action==='product-story'){closeModal();navigate('founder');}if(action==='open-checkin')showModal('checkin');
if(action==='toggle-task'){const t=state.tasks.find(x=>x.id===el.dataset.id);if(t){t.done=!t.done;save();render();toast(t.done?'One small promise, kept. Keep becoming.':'Promise moved back to your plan.');}}
if(action==='filter'){goalFilter=el.dataset.filter;render();}
if(action==='goal-detail'){showModal('goal-detail');draft.id=el.dataset.id;drawModal();}
if(action==='journey-day'){showModal('journey-day');draft.day=el.dataset.day;drawModal();}
if(action==='save-progress'){const g=state.goals.find(x=>x.id===draft.id);const progress=Number($('#goal-progress').value);await pending(el,()=>{g.progress=progress;save();closeModal();render();toast('Your goal progress has been updated.');});}
if(action==='goal-add-action'){const g=state.goals.find(x=>x.id===draft.id);showModal('add-action');if(g)$('#action-goal').value=g.id;}
if(action==='guide-to-action'){showModal('add-action');$('#action-title').value='Protect 10 minutes for my most meaningful work';}
if(action==='energy'){captureCheckin();draft.energy=Number(el.dataset.value);drawModal();}
if(action==='checkin-next'){captureCheckin();if(modalStep===1&&draft.reflection.length<8){error('Add a short reflection of at least 8 characters.');return;}modalStep++;drawModal();}
if(action==='checkin-back'){captureCheckin();modalStep--;drawModal();}
if(action==='save-checkin'){captureCheckin();if(draft.promise.length<4){error('Give your next step a little detail (at least 4 characters).');return;}await pending(el,()=>{state.checkin={...draft,date:todayKey()};const id='checkin-'+todayKey();state.entries=state.entries.filter(x=>x.id!==id);state.entries.unshift({id,date:new Date().toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'}),title:'A little more aligned.',text:draft.reflection,value:state.values[0]||'Growth'});if(!state.tasks.some(x=>x.title.toLowerCase()===draft.promise.toLowerCase()))state.tasks.push({id:'t'+Date.now(),title:draft.promise,goal:state.goals[0]?.title||'My future self',category:state.goals[0]?.category||'Personal',mins:10,done:false});save();render();modalStep=3;drawModal();toast('Your daily check-in is saved.');});}
if(action==='start-setup'){showModal('setup');}
if(action==='example-vision'){$('#setup-vision').value='I create meaningful work, protect my energy, and follow through on what matters to me.';toast('A starting point. Make it your own.');}
if(action==='value'){captureSetup();const v=el.dataset.value;if(draft.values.includes(v))draft.values=draft.values.filter(x=>x!==v);else if(draft.values.length<3)draft.values.push(v);else{toast('Choose up to 3 values that matter most right now.');return;}drawModal();}
if(action==='setup-next'){captureSetup();if(modalStep===0&&(!draft.name||draft.vision.length<12)){error('Add your name and a future-self vision of at least 12 characters.');return;}if(modalStep===1&&(!draft.values.length||draft.goal.length<5)){error('Choose at least one value and add a goal of at least 5 characters.');return;}modalStep++;drawModal();}
if(action==='setup-back'){captureSetup();modalStep--;drawModal();}
if(action==='example-action'){captureSetup();const c=draft.category;$('#setup-promise').value=c==='Health'?'Take a 10-minute walk before opening my inbox':c==='Relationships'?'Give someone I care about 15 minutes of undivided attention':c==='Financial'?'Spend 10 minutes reviewing my current spending':c==='Career'?'Write down the first 3 steps toward my goal':'Protect 10 minutes for my most meaningful next step';toast('A curated suggestion. Adapt it to fit your life.');}
if(action==='save-setup'){captureSetup();if(!draft.identity||!draft.growth||draft.promise.length<4){error('Add your desired identity, growth area and a small first promise.');return;}await pending(el,()=>{const fresh=seed();state={...fresh,mode:'personal',name:draft.name,vision:draft.vision,values:draft.values,identity:draft.identity,growth:draft.growth,day:1,start:todayKey(),goals:[{id:'g'+Date.now(),title:draft.goal,category:draft.category,progress:0,why:'A meaningful outcome for my next 90 days.',milestones:['Take my first small step','Review and refine my plan','Celebrate the outcome']}],tasks:[{id:'t'+Date.now(),title:draft.promise,goal:draft.goal,category:draft.category,mins:10,done:false}],checkin:null,entries:[],posts:[],rsvp:false,cheers:[]};save();closeModal();navigate('today');toast('Your journey is ready. Begin with one small promise.');});}
if(action==='save-profile'){const vision=$('#edit-vision').value.trim(),values=$('#edit-values').value.split(',').map(x=>x.trim()).filter(Boolean).slice(0,5),identity=$('#edit-identity').value.trim(),growth=$('#edit-growth').value.trim();if(vision.length<12||!values.length||!identity||!growth){error('Complete your vision, values, desired identity and growth area.');return;}await pending(el,()=>{Object.assign(state,{vision,values,identity,growth});save();closeModal();render();toast('Your north star has been updated.');});}
if(action==='save-goal'){const title=$('#goal-title').value.trim(),category=$('#goal-category').value,why=$('#goal-why').value.trim(),milestone=$('#goal-milestone').value.trim();if(title.length<5||!why||!milestone){error('Add a goal, a reason it matters, and your first milestone.');return;}await pending(el,()=>{state.goals.push({id:'g'+Date.now(),title,category,why,progress:0,milestones:[milestone]});save();goalFilter='All goals';closeModal();render();toast('A new possibility, given a direction.');});}
if(action==='save-action'){const title=$('#action-title').value.trim(),g=state.goals.find(x=>x.id===$('#action-goal').value),mins=Number($('#action-mins').value);if(title.length<4||!Number.isFinite(mins)||mins<1||mins>240){error('Add a specific promise and a time between 1 and 240 minutes.');return;}await pending(el,()=>{state.tasks.push({id:'t'+Date.now(),title,goal:g?.title||'My future self',category:g?.category||'Personal',mins,done:false});save();closeModal();render();toast('Your next small promise is on the plan.');});}
if(action==='journal-prompt'){const prompts=['What is one small promise you kept, even when it felt difficult?','Which choice felt most like the person you want to become?','What could you make easier for yourself tomorrow?','What gave you energy today, and what asked for too much?'];$('#journal-prompt-text').textContent=prompts[Math.floor(Math.random()*prompts.length)];}
if(action==='save-reflection'){const title=$('#journal-title').value.trim()||'A moment of perspective',text=$('#journal-text').value.trim();if(text.length<8){error('Give this reflection at least 8 characters.');return;}await pending(el,()=>{state.entries.unshift({id:'j'+Date.now(),date:new Date().toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'}),title,text,value:state.values[0]});save();closeModal();navigate('journal');toast('Your reflection has a place to return to.');});}
if(action==='share-post'){const text=$('#circle-post').value.trim();if(text.length<4){toast('Add a few words to share with your demo circle.');$('#circle-post').focus();return;}await pending(el,()=>{state.posts.unshift({id:'p'+Date.now(),text});save();render();toast('Saved to the demo feed. Only visible in this browser.');});}
if(action==='cheer'){const id=el.dataset.id;state.cheers=state.cheers.includes(id)?state.cheers.filter(x=>x!==id):[...state.cheers,id];save();render();toast('Demo encouragement updated. No message was sent.');}
if(action==='confirm-rsvp')await pending(el,()=>{state.rsvp=!state.rsvp;save();closeModal();render();toast(state.rsvp?'Your place is reserved in this demo.':'Your demo RSVP has been removed.');});
if(action==='toggle-notification'){state.notifications[el.dataset.id]=!state.notifications[el.dataset.id];save();render();toast('Preview preference saved. No reminders are sent.');}
if(action==='save-settings'){e.preventDefault();const name=$('#settings-name').value.trim();if(!name){toast('Add a name for your profile.');return;}await pending(el,()=>{state.name=name;save();render();toast('Your profile has been updated.');});}
if(action==='export')exportData();
if(action==='confirm-reset')await pending(el,()=>{state=seed();save();goalFilter='All goals';closeModal();navigate('today');toast('Maya’s sample journey is ready for your walkthrough.');});
});
document.addEventListener('submit',e=>e.preventDefault());
document.addEventListener('input',e=>{if(e.target.id==='alignment')$('#alignment-value').textContent=e.target.value+'/5';if(e.target.id==='goal-progress')$('#goal-progress-label').textContent=e.target.value+'%';});
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(modalType)closeModal();else{$('.sidebar')?.classList.remove('open');$('.mobile-shade')?.classList.remove('open');}}if(e.key==='Tab'&&modalType){const nodes=[...$('#modal-root').querySelectorAll('button,input,textarea,select,a[href]')].filter(n=>!n.disabled);const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}});
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if(page==='how-it-works')return;if(page!==currentPage){if(modalType)closeModal();currentPage=page==='welcome'||Object.hasOwn(pageNames,page)?page:'today';render();}});
// Theme and interaction state stay separate from the participant's growth data.
const chapterExamples=[
  {identity:'Focused. Purposeful. Brave.',goal:'Launch the consulting practice I keep imagining.',promise:'Outline the first version of my offer.'},
  {identity:'Energized. Present. Strong.',goal:'Build a movement routine that fits my real life.',promise:'Step outside for a ten-minute walk.'},
  {identity:'Present. Open. Connected.',goal:'Make more room for the people who matter.',promise:'Reach out for one meaningful conversation.'}
];
let chapterChoice=0,previewPromiseKept=false;
let visualTheme='day';
try{visualTheme=localStorage.getItem('greatnessly-theme')==='night'?'night':'day';}catch{}
let focusSession=null,focusInterval=null;
const seasons=[
  {range:'01—30',title:'Build the roots.',copy:'Clarify your vision. Choose a meaningful goal. Find a small daily rhythm you can return to.',icon:'leaf'},
  {range:'31—60',title:'Find your momentum.',copy:'Notice what works. Make the next step easier. Let your small promises become a practice.',icon:'up'},
  {range:'61—90',title:'Notice who you’re becoming.',copy:'Look back at the evidence. Celebrate your effort and choose what comes into your next chapter.',icon:'spark'}
];
function themeSwitch(){return `<button class='theme-switch' data-action='switch-theme' aria-label='Switch to ${visualTheme==='day'?'midnight':'daylight'} theme' aria-pressed='${visualTheme==='night'}'><span class='theme-switch-icon'>${icon(visualTheme==='day'?'sun':'moon')}</span><span>${visualTheme==='day'?'Daylight':'Midnight'}</span></button>`;}
function enhanceExperience(){
  document.documentElement.dataset.theme=visualTheme;
  document.querySelectorAll('.theme-control-slot').forEach(slot=>slot.innerHTML=themeSwitch());
  const actions=$('.top-actions');if(actions&&!$('.theme-switch',actions))actions.insertAdjacentHTML('afterbegin',themeSwitch());
  const hero=$('.dashboard-top .hero');
  if(hero){
    hero.classList.add('daily-hero');
    $('.eyebrow',hero).innerHTML=`<span class='hero-live-dot'></span>A LITTLE MORE ALIGNED, EVERY DAY`;
    $('h2',hero).innerHTML='Make room for<br><em>your next chapter.</em>';
    const next=state.tasks.find(t=>!t.done);
    $('.hero-bottom',hero).insertAdjacentHTML('afterend',`<div class='hero-focus-link'>${next?`<button data-action='start-focus' data-id='${esc(next.id)}'>${icon('clock')}Open my focus space ${icon('arrow')}</button>`:`<button data-action='add-action'>${icon('plus')}Make another small promise ${icon('arrow')}</button>`}</div><span class='hero-chapter-label'>${String(state.day).padStart(2,'0')}<span>/ 90 DAYS OF BECOMING</span></span>`);
  }
  document.querySelectorAll('.action-row').forEach(row=>{
    const check=$('.check-button',row);const task=state.tasks.find(t=>t.id===check?.dataset.id);
    if(task&&!task.done&&!$('.focus-shortcut',row))row.insertAdjacentHTML('beforeend',`<button class='focus-shortcut' data-action='start-focus' data-id='${esc(task.id)}' aria-label='Focus on ${esc(task.title)}' title='Open a focus session'>${icon('clock')}</button>`);
  });
  const stats=$('.stats-row');if(stats)stats.querySelectorAll('.stat').forEach((el,i)=>el.style.setProperty('--card-order',i));
}
function updateChapterPreview(){
  const example=chapterExamples[chapterChoice];
  if(!$('#preview-identity'))return;
  $('#preview-identity').textContent=example.identity;$('#preview-goal').textContent=example.goal;$('#preview-promise').textContent=example.promise;
  document.querySelectorAll('.chapter-tab').forEach((b,i)=>{b.classList.toggle('selected',i===chapterChoice);b.setAttribute('aria-pressed',i===chapterChoice);});
  const check=$('.preview-check');check.classList.toggle('is-kept',previewPromiseKept);check.setAttribute('aria-pressed',previewPromiseKept);$('.preview-checkbox',check).innerHTML=previewPromiseKept?icon('check'):'';
  $('#preview-feedback').textContent=previewPromiseKept?'That’s what showing up feels like.':'Try keeping this small promise. Click the circle.';
  $('.chapter-visual').dataset.chapter=chapterChoice;
  $('.preview-goal-bar').classList.toggle('promise-kept',previewPromiseKept);
}
function celebrate(){
  if(typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  const wrap=document.createElement('div');wrap.className='little-celebration';wrap.setAttribute('aria-hidden','true');
  wrap.innerHTML=Array.from({length:18},(_,i)=>`<i style='--x:${(i%9-4)*38}px;--y:${-75-(i%5)*28}px;--r:${i*47}deg;--delay:${i%3*25}ms;--particle-color:${['#bafa78','#4dcbb3','#e8c576','#b4baf3'][i%4]}'></i>`).join('');
  document.body.appendChild(wrap);setTimeout(()=>wrap.remove(),1250);
}
function stopFocusTimer(){if(focusInterval){clearInterval(focusInterval);focusInterval=null;}if(focusSession?.running){focusSession.remaining=Math.max(0,Math.ceil((focusSession.endAt-Date.now())/1000));focusSession.running=false;}}
function openFocusSpace(id){
  const task=state.tasks.find(t=>t.id===id&&!t.done)||state.tasks.find(t=>!t.done);
  if(!task){showModal('add-action');return;}
  stopFocusTimer();lastFocus=document.activeElement;modalType='focus';focusSession={taskId:task.id,title:task.title,total:600,remaining:600,running:false,endAt:null};document.body.style.overflow='hidden';drawFocusSpace();
}
function drawFocusSpace(){
  const f=focusSession;if(!f)return;
  $('#modal-root').innerHTML=`<div class='modal-backdrop'><section class='modal focus-modal' role='dialog' aria-modal='true' aria-labelledby='modal-title'><button class='icon-btn modal-close' data-action='close-modal' aria-label='Close focus space'>${icon('close')}</button><div class='eyebrow'>ONE PROMISE. A LITTLE PROTECTED TIME.</div><h2 id='modal-title'>This moment is yours.</h2><p class='focus-task'>${esc(f.title)}</p><div class='focus-timer' style='--timer-progress:0deg'><div class='focus-timer-center'><span class='focus-timer-caption'>YOUR FOCUS SPACE</span><strong id='focus-time' role='timer' aria-label='Time remaining'>${Math.floor(f.remaining/60).toString().padStart(2,'0')}:${(f.remaining%60).toString().padStart(2,'0')}</strong><span id='focus-state'>A small beginning is enough.</span></div></div><div class='focus-presets' role='group' aria-label='Choose a focus duration'>${[5,10,25].map(n=>`<button data-action='focus-duration' data-value='${n}' class='${f.total===n*60?'selected':''}' aria-pressed='${f.total===n*60}'>${n} min</button>`).join('')}</div><button class='btn btn-primary focus-start' data-action='focus-toggle'>${icon('clock')}<span>Begin my focus session</span></button><button class='text-button focus-finish' data-action='finish-focus'>${icon('check')}I kept this promise</button><p class='focus-note'>Closing this space stops the timer. Mark your promise complete when you’ve done it.</p></section></div>`;
  requestAnimationFrame(()=>$('.focus-start')?.focus());
}
function updateFocusTimer(){
  const f=focusSession;if(!f||modalType!=='focus')return;
  if(f.running)f.remaining=Math.max(0,Math.ceil((f.endAt-Date.now())/1000));
  const time=$('#focus-time');if(!time)return;
  time.textContent=`${Math.floor(f.remaining/60).toString().padStart(2,'0')}:${(f.remaining%60).toString().padStart(2,'0')}`;
  $('.focus-timer').style.setProperty('--timer-progress',`${(1-f.remaining/f.total)*360}deg`);
  if(f.remaining===0&&f.running){stopFocusTimer();$('#focus-state').textContent='Your protected time is complete.';$('.focus-start span').textContent='Start another session';celebrate();toast('Your focus time is complete. Take a moment to notice your progress.');}
}
function toggleFocus(){
  const f=focusSession;if(!f)return;
  if(f.running){stopFocusTimer();$('#focus-state').textContent='Paused. Take the space you need.';$('.focus-start span').textContent='Continue my focus session';}
  else{if(f.remaining===0)f.remaining=f.total;f.running=true;f.endAt=Date.now()+f.remaining*1000;focusInterval=setInterval(updateFocusTimer,250);$('#focus-state').textContent='Just this promise. Just this moment.';$('.focus-start span').textContent='Pause my focus session';}
  document.querySelectorAll('[data-action=focus-duration]').forEach(b=>b.disabled=f.running);
}
document.addEventListener('click',e=>{
  const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;
  if(action==='switch-theme'){visualTheme=visualTheme==='day'?'night':'day';try{localStorage.setItem('greatnessly-theme',visualTheme);}catch{}document.documentElement.dataset.theme=visualTheme;document.querySelectorAll('.theme-switch').forEach(b=>{const box=document.createElement('div');box.innerHTML=themeSwitch();const focused=document.activeElement===b;const next=box.firstElementChild;b.replaceWith(next);if(focused)next.focus();});}
  if(action==='preview-chapter'){chapterChoice=Number(el.dataset.value);previewPromiseKept=false;updateChapterPreview();}
  if(action==='preview-promise'){previewPromiseKept=!previewPromiseKept;updateChapterPreview();if(previewPromiseKept)celebrate();}
  if(action==='toggle-task'&&state.tasks.find(t=>t.id===el.dataset.id)?.done)celebrate();
  if(action==='start-focus')openFocusSpace(el.dataset.id);
  if(action==='focus-duration'&&!focusSession?.running){const n=Number(el.dataset.value);focusSession.total=n*60;focusSession.remaining=n*60;drawFocusSpace();}
  if(action==='focus-toggle')toggleFocus();
  if(action==='finish-focus'&&focusSession){const task=state.tasks.find(t=>t.id===focusSession.taskId);if(task){task.done=true;save();}closeModal();render();celebrate();toast('A little protected time. A promise kept. Beautiful work.');}
});
document.addEventListener('input',e=>{
  if(e.target.id!=='journey-preview')return;const day=Number(e.target.value);const phase=Math.min(2,Math.floor((day-1)/30));const season=seasons[phase];
  $('#journey-preview-day').textContent='Day '+day;$('#season-range').textContent=season.range;$('#season-index').textContent=String(phase+1).padStart(2,'0');$('#season-title').textContent=season.title;$('#season-copy').textContent=season.copy;$('.season-mark').innerHTML=icon(season.icon);$('.season-card').dataset.season=phase;
});

const initial=location.hash.slice(1);currentPage=initial==='welcome'||Object.hasOwn(pageNames,initial)?initial:(state.mode==='personal'?'today':'welcome');render();
if(!storageOkay)toast('Browser storage is unavailable. You can still explore this preview.');
